package com.driveflow.servlet;
import com.driveflow.model.*; import com.driveflow.store.DataStore; import com.driveflow.util.Flash; import javax.servlet.*; import javax.servlet.http.*; import java.io.IOException; import java.time.LocalDateTime;
public class PaymentServlet extends HttpServlet {
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{req.setAttribute("payments",DataStore.payments);req.setAttribute("rentals",DataStore.rentals);req.getRequestDispatcher("/views/payments.jsp").forward(req,resp);}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{try{int rid=Integer.parseInt(req.getParameter("rentalId"));double amount=Double.parseDouble(req.getParameter("amount"));Rental r=DataStore.rental(rid);if(r==null)throw new IllegalArgumentException("Rental not found.");if(amount<=0||amount>r.getTotalAmount())throw new IllegalArgumentException("Payment must be greater than 0 and not exceed the rental total.");Payment.Method method=Payment.Method.valueOf(req.getParameter("method"));DataStore.payments.add(new Payment(DataStore.nextPaymentId(),rid,amount,method,Payment.Status.PAID,LocalDateTime.now()));Flash.set(req.getSession(),"success","Payment recorded successfully.");}catch(Exception e){Flash.set(req.getSession(),"error","Could not record payment: "+e.getMessage());}resp.sendRedirect(req.getContextPath()+"/payments");}
}
